const articles = [
  {
    title: "Password Reset and Account Lockout",
    text: "Accounts lock for 15 minutes after 5 failed sign-in attempts. To reset a password, go to the self-service portal at password.example.com and confirm your identity with your MFA code. If a laptop keeps asking for a password every few minutes, sign out and back in, then remove old saved credentials. Also update the new password on your phone and any other device, because an old saved password on another device can keep locking the account. If you cannot receive an MFA code, the help desk must verify your identity before resetting access."
  },
  {
    title: "VPN Connection Problems",
    text: "If the VPN will not connect, first confirm your home internet works. Restart the VPN client and make sure it is on the latest version. If you see an authentication failed error, reset your password and try again. If the VPN still fails after two attempts, open a ticket and include the exact error message and the time it happened."
  },
  {
    title: "Printer Troubleshooting",
    text: "If a printer is not responding, check that it is powered on and shows as online. Remove the printer from your computer and add it again from the printer list. Clear any paper jams and confirm there is paper and toner. If the printer still fails, note the printer name and location in a ticket."
  },
  {
    title: "Reporting Suspicious Emails",
    text: "Do not click links or open attachments in suspicious emails. Use the Report Phishing button in your email program. If you already clicked a link or entered your password, treat it as a security incident: disconnect from the network and contact the security team immediately. Security incidents must always be reviewed by a human and are never resolved automatically."
  },
  {
    title: "Software Installation Requests",
    text: "Only install approved software from the Company Portal. Software that is not in the portal needs manager approval and a security review, which takes about 3 business days. Submit the software name, version, and business reason in a ticket."
  }
];

return articles.map(a => ({ json: a }));
